package com.optarena;

import java.util.List;

public class Evens {
    // Remove every even number from the list, in place.
    // BUG: removing from the list while iterating it with a for-each loop
    // throws ConcurrentModificationException at runtime.
    public void removeEvens(List<Integer> nums) {
        for (Integer n : nums) {
            if (n % 2 == 0) {
                nums.remove(n);
            }
        }
    }
}

