package com.optarena;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import org.junit.jupiter.api.Test;

class EvensHiddenTest {

    @Test
    void removesEvensKeepsOddsInOrder() {
        List<Integer> nums = new ArrayList<>(Arrays.asList(1, 2, 3, 4, 5, 6));
        new Evens().removeEvens(nums);
        assertEquals(Arrays.asList(1, 3, 5), nums);
    }

    @Test
    void allEvensBecomesEmpty() {
        List<Integer> nums = new ArrayList<>(Arrays.asList(2, 4, 6));
        new Evens().removeEvens(nums);
        assertEquals(List.of(), nums);
    }

    @Test
    void noEvensUnchanged() {
        List<Integer> nums = new ArrayList<>(Arrays.asList(1, 3, 5));
        new Evens().removeEvens(nums);
        assertEquals(Arrays.asList(1, 3, 5), nums);
    }
}

